def sem(rs1, rs2, state):
    # rs1: uint32 bieu dien int32 co dau; rs2: so bit dich phai
    s = rs1 - 0x100000000 if rs1 >= 0x80000000 else rs1
    sh = rs2 & 0x1F
    if sh:
        s = (s + (1 << (sh - 1))) >> sh   # lam tron nua len, dich phai so hoc
    if s < -128:
        s = -128
    elif s > 127:
        s = 127
    return (s & 0xFF), state

def sem(rs1, rs2, state):
    s = rs1 - 0x100000000 if rs1 >= 0x80000000 else rs1
    relu = (rs2 & 1) == 1   # bien the funct7=1 duoc giai ma thanh bit nay
    lo = 0 if relu else -128
    if s < lo:
        s = lo
    elif s > 127:
        s = 127
    return (s & 0xFF), state

def sem(rs1, rs2, state):
    # state['mem'] la mang byte; state['funct3'] chon be rong truy cap
    mem = state['mem']
    addr = rs1 & 0xFFFFFFFF
    if state.get('funct3', 0) == 0:
        rd = mem[addr] & 0xFF
    else:
        rd = (mem[addr] | (mem[addr + 1] << 8) | (mem[addr + 2] << 16) | (mem[addr + 3] << 24)) & 0xFFFFFFFF
    state['base_next'] = (addr + rs2) & 0xFFFFFFFF   # ghi lai vao so hieu thanh ghi rs1
    return rd, state
